export default function AdminControlCenterSpec(){
 const [token,setToken]=useState(()=>sessionStorage.getItem(TOKEN_KEY)||"");const [active,setActive]=useState("dashboard");const [child,setChild]=useState("");const [search,setSearch]=useState("");const [mobile,setMobile]=useState(false);const [dark,setDark]=useState(()=>localStorage.getItem("admin-theme")==="dark");const [busy,setBusy]=useState(false);const [toast,setToast]=useState("");
 const [data,setData]=useState<R>({events:[],guestbook:[],notifications:[],rsvps:[],backups:[],trash:[],audit:[],settings:{},analytics:{},sections:[]});
 const modules=useMemo(()=>{const q=search.trim().toLowerCase();return q?ADMIN_MODULES.filter(m=>`${m.label} ${m.description} ${m.children.map(c=>c.label).join(" ")}`.toLowerCase().includes(q)):ADMIN_MODULES},[search]);const current=ADMIN_MODULES.find(m=>m.id===active)||ADMIN_MODULES[0];const tabs=current.children;const selected=tabs.some(x=>x.id===child)?child:tabs[0]?.id||"";
 useEffect(()=>{document.documentElement.classList.toggle("dark",dark);localStorage.setItem("admin-theme",dark?"dark":"light")},[dark]);useEffect(()=>{if(!tabs.some(x=>x.id===child))setChild(tabs[0]?.id||"")},[active,tabs,child]);
 const notify=(v:string)=>{setToast(v);window.setTimeout(()=>setToast(""),3500)};
 const load=async()=>{if(!token)return;setBusy(true);try{const ok=await supabaseRest<boolean>("rpc/is_admin",{method:"POST",token,body:{}});if(!ok)throw new Error("Administrator authorization denied.");const [events,guestbook,notifications,rsvps,backups,trash,audit,settings,analytics,sections]=await Promise.all([getAdminEvents(token),getAdminFeaturedGuestbook(token),getNotifications(token),getAdminRsvps(token),getAdminBackups(token),getTrashItems(token),getAuditLogs(token),getAdminSettings(token),getAdminAnalytics(token),getAdminHomepageSections(token)]);setData({events:events||[],guestbook:guestbook||[],notifications:notifications||[],rsvps:rsvps||[],backups:backups||[],trash:trash||[],audit:audit||[],settings:Object.fromEntries((settings||[]).map(x=>[x.key,x.value])),analytics:analytics||{},sections:sections||[]})}catch(e){notify(e instanceof Error?e.message:"Unable to load admin data.")}finally{setBusy(false)}};useEffect(()=>{void load()},[token]);
 if(!token)return <div className="grid min-h-screen place-items-center p-6"><div className="rounded-3xl border bg-card p-8 text-center"><ShieldCheck className="mx-auto mb-3"/><h1 className="text-2xl font-semibold">Admin session required</h1><p className="mt-2 text-sm text-muted-foreground">Sign in again to continue.</p></div></div>;
 const go=(id:string)=>{setActive(id);setMobile(false);window.scrollTo({top:0,behavior:"smooth"})};const logout=()=>{sessionStorage.removeItem(TOKEN_KEY);sessionStorage.removeItem(REFRESH_KEY);setToken("")};
 return <div className="min-h-screen bg-muted/20"><header className="sticky top-0 z-50 border-b bg-background/95 backdrop-blur"><div className="flex h-16 items-center gap-2 px-3 md:px-5"><Btn onClick={()=>setMobile(true)}><Menu size={18}/></Btn><button onClick={()=>go("dashboard")} className="flex items-center gap-2 font-semibold"><span className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-primary-foreground"><Sparkles size={17}/></span><span className="hidden sm:block">Wedding Admin</span></button><div className="relative ml-auto hidden max-w-md flex-1 md:block"><Search className="absolute left-3 top-1/2 -translate-y-1/2" size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search modules or selections…" className="h-10 w-full rounded-xl border pl-9"/></div><Btn onClick={()=>setDark(v=>!v)}>{dark?<Sun size={17}/>:<Moon size={17}/>}</Btn><Btn onClick={()=>void load()} disabled={busy}><RefreshCw className={busy?"animate-spin":""} size={16}/></Btn><Btn onClick={logout}><LogOut size={16}/></Btn></div></header><div className="flex"><aside className="sticky top-16 hidden h-[calc(100vh-4rem)] w-72 shrink-0 overflow-y-auto border-r bg-background p-3 md:block">{GROUPS.map(g=><div key={g} className="mb-5"><div className="px-2 py-2 text-[10px] font-semibold tracking-widest text-muted-foreground">{GROUP_LABELS[g]}</div>{modules.filter(m=>m.group===g).map(m=><button key={m.id} onClick={()=>go(m.id)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm ${active===m.id?"bg-primary text-primary-foreground":"hover:bg-muted"}`}><m.icon size={17}/><span className="truncate">{m.number}. {m.label}</span></button>)}</div>)}</aside>{mobile&&<div className="fixed inset-0 z-[70] md:hidden"><button aria-label="Close navigation" className="absolute inset-0 bg-black/40" onClick={()=>setMobile(false)}/><aside className="relative h-full w-[90vw] max-w-sm overflow-y-auto bg-background p-4"><div className="mb-4 flex justify-between"><b>Administration</b><Btn onClick={()=>setMobile(false)}><X size={17}/></Btn></div>{modules.map(m=><button key={m.id} onClick={()=>go(m.id)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left ${active===m.id?"bg-primary text-primary-foreground":"hover:bg-muted"}`}><m.icon size={17}/><span>{m.number}. {m.label}</span></button>)}</aside></div>}<main className="min-w-0 flex-1 p-3 sm:p-5 md:p-7"><div className="mx-auto max-w-[1550px]"><div className="mb-5"><div className="text-xs text-muted-foreground">Admin <ChevronRight size={12} className="inline"/> {current.number}. {current.label}</div><h1 className="mt-1 text-2xl font-semibold sm:text-3xl">{current.label}</h1><p className="mt-1 max-w-4xl text-sm text-muted-foreground">{current.description}</p></div>{active==="dashboard"?<Dashboard data={data} go={go}/>:<Module module={current} selected={selected} setSelected={setChild} token={token} data={data} setData={setData} notify={notify}/>}</div></main></div>{toast&&<div role="status" className="fixed bottom-5 right-5 z-[100] max-w-xl rounded-2xl border bg-background p-4 text-sm shadow-xl">{toast}</div>}</div>}

function Dashboard({data,go}:{data:R;go:(id:string)=>void}){const pending=data.rsvps.filter((x:any)=>x.attending==null).length;return <div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{[["Events",data.events.length,"events"],["Pending RSVP",pending,"rsvp"],["Guestbook",data.guestbook.length,"guestbook"],["Visitors",data.analytics.total||0,"analytics"],["Backups",data.backups.length,"backup"]].map(([l,v,id])=><button key={String(l)} onClick={()=>go(String(id))} className="rounded-2xl border bg-card p-4 text-left"><div className="text-xs text-muted-foreground">{l}</div><div className="mt-2 text-3xl font-semibold">{v}</div></button>)}</div><Card title="Quick Links"><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{["website","styling","alerts","rsvp","guestbook","social","media","analytics","publishing","diagnostics","integrations","backup","settings"].map(id=><Btn key={id} onClick={()=>go(id)}>{title(id)}<ChevronRight size={15}/></Btn>)}</div></Card><Card title="System Health"><div className="grid gap-3 md:grid-cols-3">{[{n:"Supabase",ok:isSupabaseConfigured},{n:"Admin data",ok:true},{n:"Draft workspace",ok:true}].map(x=><div key={x.n} className="rounded-xl border p-3"><b>{x.n}</b><div className="text-xs text-muted-foreground">{x.ok?"Ready":"Not configured"}</div></div>)}</div></Card></div>}

function Module({module,selected,setSelected,token,data,setData,notify}:{module:AdminModule;selected:string;setSelected:(v:string)=>void;token:string;data:R;setData:(v:R)=>void;notify:(v:string)=>void}){return <div className="space-y-4"><div className="rounded-2xl border bg-background p-2"><div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">{module.children.map(c=><button key={c.id} onClick={()=>setSelected(c.id)} className={`min-h-11 rounded-xl border px-3 py-2 text-left text-sm ${selected===c.id?"border-primary bg-primary text-primary-foreground":"hover:bg-muted"}`}><span className="block truncate">{title(c.id)}</span><span className={`text-[11px] ${selected===c.id?"text-primary-foreground/80":"text-muted-foreground"}`}>{c.description||`Manage ${title(c.id).toLowerCase()}.`}</span></button>)}</div></div><Content module={module} selected={selected} token={token} data={data} setData={setData} notify={notify}/></div>}

function Content(p:{module:AdminModule;selected:string;token:string;data:R;setData:(v:R)=>void;notify:(v:string)=>void}){const {module,selected}=p;if(module.id==="events")return <Events {...p}/>;if(module.id==="website"&&selected!=="section-manager"){const childMap:any={home:"home",couple:"couple","events-story-memory":"story","gallery-highlights":"gallery",rsvp:"rsvp",guestbook:"guestbook",footer:"footer",navigation:"navigation"};if(childMap[selected])return <WebsiteContentPanel child={childMap[selected]} token={p.token} settings={p.data.settings} setSettings={(v:any)=>p.setData({...p.data,settings:typeof v==="function"?v(p.data.settings):v})} notify={p.notify}/>;}if(module.id==="rsvp")return <RSVP {...p}/>;if(module.id==="guestbook")return <Guestbook {...p}/>;if(module.id==="notifications")return <Notifications {...p}/>;if(module.id==="analytics")return <Analytics {...p}/>;if(module.id==="audit")return <Audit {...p}/>;if(module.id==="backup")return <Backup {...p}/>;if(module.id==="trash")return <Trash {...p}/>;if(module.id==="publishing")return <Publishing {...p}/>;if(module.id==="diagnostics")return <Diagnostics {...p}/>;if(module.id==="website"&&selected==="section-manager")return <Sections {...p}/>;return <SpecEditor {...p}/>}

