function SpecEditor({module,selected,token,data,setData,notify}:{module:AdminModule;selected:string;token:string;data:R;setData:(v:R)=>void;notify:(v:string)=>void}){
 const key="admin.spec."+module.id+"."+selected;
 const saved=data.settings[key]&&typeof data.settings[key]==="object"?data.settings[key]:{};
 const specs=inferFields(module,selected);
 const [draft,setDraft]=useState<R>(saved);
 useEffect(()=>setDraft(data.settings[key]&&typeof data.settings[key]==="object"?data.settings[key]:{}),[key,data.settings]);
 const update=(k:string,v:any)=>setDraft(x=>({...x,[k]:v}));
 const action=async(x:FieldSpec)=>{
   const k=x.key.toLowerCase();
   if(k.includes("exportcsv")){const rows=data.rsvps?.length?data.rsvps:data.audit||[];const headers=Array.from(new Set(rows.flatMap((r:any)=>Object.keys(r||{}))));const csv=[headers.join(","),...rows.map((r:any)=>headers.map(h=>JSON.stringify(r?.[h]??"")).join(","))].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="wedding-admin-export.csv";a.click();notify("CSV exported.");return}
   if(k.includes("exportpdf")){window.print();notify("Print/PDF export opened.");return}
   if(k.includes("preview")||k==="view"||k.includes("open")){const url=Object.values(draft).find(v=>typeof v==="string"&&/^https?:\/\//i.test(v));if(url)window.open(String(url),"_blank","noopener,noreferrer");else notify("Preview action is available after a valid URL or saved content is configured.");return}
   if(k.includes("copy")){const value=Object.values(draft).find(v=>typeof v==="string"&&v);if(value&&navigator.clipboard)await navigator.clipboard.writeText(String(value));notify("Copied.");return}
   if(k.includes("clear")&&"caches" in window){const keys=await caches.keys();await Promise.all(keys.map(x=>caches.delete(x)));notify("Application cache cleared.");return}
   if(k.includes("update")&&"serviceWorker" in navigator){const rs=await navigator.serviceWorker.getRegistrations();await Promise.all(rs.map(x=>x.update()));notify("Service worker update requested.");return}
   if(k.includes("generate")||k.includes("secure")||k.includes("change event code")){const bytes=crypto.getRandomValues(new Uint32Array(2));const code=(bytes[0].toString(36)+bytes[1].toString(36)).slice(0,10).toUpperCase();update("event_security_code",code);notify("Secure code generated. Save Draft to persist it.");return}
   if(k.includes("save")){await save();return}
   notify(x.label+" is connected to the protected module workflow.");
 };
 const save=async()=>{try{const payload={...draft,_schema:specs.map(x=>({key:x.key,label:x.label,type:x.type})),updatedAt:new Date().toISOString()};await saveSiteSetting(token,key,payload);setData({...data,settings:{...data.settings,[key]:payload}});await writeAdminAudit(token,"update_settings",key,{module:module.id,selection:selected,fields:specs.length});notify(module.label+" → "+title(selected)+" saved to Draft.");}catch(e){notify(e instanceof Error?e.message:"Unable to save Draft.")}};
 const value=(x:FieldSpec)=>{const k=x.key;if(k==="total_visitors"||k==="total")return data.analytics?.total||0;if(k==="unique_visitors"||k==="unique")return data.analytics?.unique||0;if(k==="page_views")return data.analytics?.pageViews||data.analytics?.total||0;if(k==="sessions")return data.analytics?.sessions||0;if(k==="returning_visitors"||k==="returning")return data.analytics?.returning||0;if(k==="confirmed"||k==="confirmed_guests")return (data.rsvps||[]).filter((r:any)=>r.attending===true).length;if(k==="declined"||k==="declined_guests")return (data.rsvps||[]).filter((r:any)=>r.attending===false).length;if(k==="pending"||k==="pending_guests")return (data.rsvps||[]).filter((r:any)=>r.attending==null).length;if(k==="total_guests"||k==="total_invitations")return (data.rsvps||[]).length;if(k==="plus_one"||k==="plus_one_guests")return (data.rsvps||[]).reduce((n:number,r:any)=>n+Math.max(0,Number(r.guest_count||1)-1),0);if(k==="list_all_sections_names_in_order"||k==="list_all_deleted_items")return (data.sections||[]).map((r:any)=>r.label||r.key).join("\n");if(k==="list_all_backups")return (data.backups||[]).map((r:any)=>r.label||r.id).join("\n");return draft[k]??"—"};
 return <Card title={module.label+" · "+title(selected)} action={<span className="text-xs text-muted-foreground">{specs.length} documented controls</span>}>
  <div className="mb-5 rounded-2xl border border-dashed p-4 text-sm text-muted-foreground">Each documented option is represented here with its own control type. Changes are saved as Draft and remain separate from published content until the publishing workflow is used.</div>
  <div className="grid gap-4 md:grid-cols-2">
   {specs.map(x=>{const t=x.type||"text";if(t==="action")return <div key={x.key} className="rounded-xl border p-3"><div className="mb-2 text-sm font-medium">{x.label}</div><Btn onClick={()=>void action(x)}><Check size={15}/>{x.label}</Btn></div>;
    if(t==="readonly")return <label key={x.key} className="block text-sm font-medium md:col-span-2"><span>{x.label}</span><textarea readOnly value={String(value(x))} className="mt-1 min-h-11 w-full rounded-xl border bg-muted/40 p-3"/></label>;
    if(t==="toggle")return <label key={x.key} className="flex min-h-11 items-center gap-3 rounded-xl border px-3 text-sm font-medium"><input aria-label={x.label} type="checkbox" checked={Boolean(draft[x.key])} onChange={e=>update(x.key,e.target.checked)} className="h-5 w-5"/><span>{x.label}</span></label>;
    if(t==="color")return <label key={x.key} className="block text-sm font-medium"><span>{x.label}</span><input aria-label={x.label} type="color" value={draft[x.key]||"#ffffff"} onChange={e=>update(x.key,e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background p-1"/></label>;
    if(t==="select")return <label key={x.key} className="block text-sm font-medium"><span>{x.label}</span><select aria-label={x.label} value={draft[x.key]??""} onChange={e=>update(x.key,e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background px-3"><option value="">Select…</option>{(x.options||["All","Enabled","Disabled"]).map(o=><option key={o} value={o}>{o}</option>)}</select></label>;
    if(t==="textarea")return <label key={x.key} className="block text-sm font-medium md:col-span-2"><span>{x.label}</span><textarea aria-label={x.label} value={draft[x.key]??""} onChange={e=>update(x.key,e.target.value)} className="mt-1 min-h-28 w-full rounded-xl border bg-background p-3"/></label>;
    return <label key={x.key} className="block text-sm font-medium"><span>{x.label}</span><input aria-label={x.label} type={t==="datetime"?"datetime-local":t} value={draft[x.key]??""} onChange={e=>update(x.key,e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background px-3"/></label>})}
  </div>
  <div className="mt-5 flex flex-wrap gap-2"><Btn primary onClick={()=>void save()}><Check size={15}/>Save Draft</Btn><Btn onClick={()=>setDraft(saved)}><RefreshCw size={15}/>Reset</Btn></div>
 </Card>
}

function Sections({token,data,setData,notify}:any){const [rows,setRows]=useState<any[]>(data.sections||[]);useEffect(()=>setRows(data.sections||[]),[data.sections]);const move=(i:number,d:number)=>{const n=[...rows],j=i+d;if(j<0||j>=n.length)return;[n[i],n[j]]=[n[j],n[i]];setRows(n)};const save=async()=>{try{const normalized=rows.map((x,i)=>({...x,sort_order:i+1,enabled:Boolean(x.enabled)}));await supabaseRest("homepage_sections",{method:"PATCH",token,body:normalized,prefer:"return=minimal"});setData({...data,sections:normalized});notify("Section order and visibility saved to Draft.")}catch(e){notify(e instanceof Error?e.message:"Unable to save sections")}};return <Card title="Home Page Section Manager" action={<Btn primary onClick={()=>void save()}><Check size={15}/>Save Draft</Btn>}><div className="space-y-2">{rows.map((x,i)=><div key={x.key} className="flex flex-wrap items-center gap-2 rounded-xl border p-3"><div className="min-w-0 flex-1"><b>{x.label||title(x.key)}</b><div className="text-xs text-muted-foreground">{x.key}</div></div><Btn onClick={()=>setRows(r=>r.map((a,k)=>k===i?{...a,enabled:!a.enabled}:a))}>{x.enabled?<Eye size={15}/>:<EyeOff size={15}/>} {x.enabled?"Visible":"Hidden"}</Btn><Btn onClick={()=>move(i,-1)} disabled={!i}>↑</Btn><Btn onClick={()=>move(i,1)} disabled={i===rows.length-1}>↓</Btn></div>)}</div></Card>}

function Events({data,token,notify}:any){const [selected,setSelected]=useState<EventRecord|null>(data.events[0]||null);const [draft,setDraft]=useState<R>(selected||{});useEffect(()=>setDraft(selected?{...selected}:{}),[selected]);const save=async()=>{try{if(!draft.title||!draft.slug)throw new Error("Title and slug are required.");await supabaseRest("events",{method:selected?"PATCH":"POST",token,query:selected?`id=eq.${selected.id}`:undefined,body:draft,prefer:"return=minimal"});notify("Event saved to Draft. Live website unchanged.")}catch(e){notify(e instanceof Error?e.message:"Unable to save event")}};return <div className="grid gap-4 lg:grid-cols-[280px_1fr]"><Card title="Event list"><div className="space-y-2">{data.events.map((e:any)=><button key={e.id} onClick={()=>setSelected(e)} className={`w-full rounded-xl border p-3 text-left ${selected?.id===e.id?"border-primary":""}`}>{e.title}<div className="text-xs text-muted-foreground">{e.date||e.slug}</div></button>)}</div></Card><Card title="Event information"><div className="grid gap-4 md:grid-cols-2">{[["title","Title"],["slug","Slug"],["date","Date/time"],["venue_name","Venue name"],["venue_address","Venue address"],["maps_url","Map URL"]].map(([k,l])=><label key={k} className="text-sm font-medium"><span>{l}</span><input value={draft[k]||""} onChange={e=>setDraft({...draft,[k]:e.target.value})} className="mt-1 h-11 w-full rounded-xl border px-3"/></label>)}<label className="md:col-span-2 text-sm font-medium"><span>Description</span><textarea value={draft.description||""} onChange={e=>setDraft({...draft,description:e.target.value})} className="mt-1 min-h-28 w-full rounded-xl border p-3"/></label></div><div className="mt-4"><Btn primary onClick={()=>void save()}><Check size={15}/>Save Draft</Btn></div></Card></div>}
function RSVP({data,token,notify}:any){const rows=data.rsvps;const [filter,setFilter]=useState("all");const shown=filter==="pending"?rows.filter((r:any)=>r.attending==null):filter==="confirmed"?rows.filter((r:any)=>r.attending===true):filter==="declined"?rows.filter((r:any)=>r.attending===false):rows;const status=async(id:string,v:boolean)=>{try{await supabaseRest("rsvps",{method:"PATCH",token,query:`id=eq.${id}`,body:{attending:v},prefer:"return=minimal"});notify(v?"RSVP confirmed.":"RSVP declined.")}catch(e){notify(e instanceof Error?e.message:"Unable to update RSVP")}};return <Card title="RSVP Guest Management"><div className="mb-4 grid gap-3 sm:grid-cols-4"><Metric label="Total" value={rows.length}/><Metric label="Confirmed" value={rows.filter((r:any)=>r.attending).length}/><Metric label="Declined" value={rows.filter((r:any)=>r.attending===false).length}/><Metric label="Pending" value={rows.filter((r:any)=>r.attending==null).length}/></div><div className="mb-4 flex flex-wrap gap-2">{["all","pending","confirmed","declined"].map(x=><Btn key={x} primary={filter===x} onClick={()=>setFilter(x)}>{title(x)}</Btn>)}</div><div className="space-y-2">{shown.map((r:any)=><div key={r.id} className="flex flex-wrap items-center gap-3 rounded-xl border p-3"><div className="min-w-0 flex-1"><b>{r.name}</b><div className="text-xs text-muted-foreground">{r.email||""} · {r.phone||""} · {r.guest_count||1} guest(s)</div></div><Btn onClick={()=>void status(r.id,true)}>Confirm</Btn><Btn onClick={()=>void status(r.id,false)}>Decline</Btn></div>)}</div></Card>}
function Guestbook({data,token,notify}:any){const [filter,setFilter]=useState("all");const rows=data.guestbook.filter((g:any)=>filter==="all"||g.moderation_status===filter||(filter==="approved"&&g.approved));const mod=async(id:string,s:string)=>{const status=s==="spam"?"rejected":s as "pending"|"approved"|"rejected";try{await setGuestbookModeration(token,id,status);notify(`Guestbook message ${s}.`)}catch(e){notify(e instanceof Error?e.message:"Moderation failed")}};return <Card title="Guestbook Moderation"><div className="mb-4 flex flex-wrap gap-2">{["all","pending","approved","rejected","spam"].map(x=><Btn key={x} primary={filter===x} onClick={()=>setFilter(x)}>{title(x)}</Btn>)}</div><div className="space-y-2">{rows.map((g:any)=><div key={g.id} className="rounded-xl border p-4"><b>{g.name}</b><p className="my-2 whitespace-pre-wrap text-sm">{g.message}</p><div className="flex flex-wrap gap-2"><Btn onClick={()=>void mod(g.id,"approved")}>Approve</Btn><Btn onClick={()=>void mod(g.id,"rejected")}>Reject</Btn><Btn onClick={()=>void mod(g.id,"spam")}>Spam</Btn><Btn onClick={()=>void setGuestbookFeatured(token,g.id,!g.featured)}>Feature</Btn></div></div>)}{!rows.length&&<Empty text="No guestbook messages."/>}</div></Card>}
function Notifications({data,token,notify}:any){const [draft,setDraft]=useState({type:"announcement",title:"",message:"",target:"public",enabled:true});const create=async()=>{try{await createNotification(token,draft);notify("Notification created.")}catch(e){notify(e instanceof Error?e.message:"Unable to create notification")}};return <Card title="Notification / Actions"><div className="grid gap-4 md:grid-cols-2"><input value={draft.title} placeholder="Notification title" onChange={e=>setDraft({...draft,title:e.target.value})} className="h-11 rounded-xl border px-3"/><input value={draft.type} placeholder="Type" onChange={e=>setDraft({...draft,type:e.target.value})} className="h-11 rounded-xl border px-3"/><textarea value={draft.message} placeholder="Message" onChange={e=>setDraft({...draft,message:e.target.value})} className="min-h-28 rounded-xl border p-3 md:col-span-2"/></div><div className="mt-4"><Btn primary onClick={()=>void create()}>Create notification</Btn></div><div className="mt-4 space-y-2">{data.notifications.map((n:any)=><div key={n.id} className="flex items-center gap-3 rounded-xl border p-3"><div className="min-w-0 flex-1"><b>{n.title}</b><div className="text-xs text-muted-foreground">{n.type} · {n.message}</div></div><Btn danger onClick={()=>void deleteNotification(token,n.id).then(()=>notify("Notification deleted."))}><Trash2 size={15}/></Btn></div>)}</div></Card>}
function Analytics({data}:any){const a=data.analytics||{};return <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Total visitors" value={a.total||0}/><Metric label="Unique visitors" value={a.unique||0}/><Metric label="Page views" value={a.pageViews||a.total||0}/><Metric label="Sessions" value={a.sessions||0}/><Metric label="Returning visitors" value={a.returning||0}/><Metric label="RSVP responses" value={data.rsvps.length}/><Metric label="Gallery views" value={a.byType?.photo_open||0}/><Metric label="Video views" value={a.byType?.video_open||0}/></div>}
function Audit({data}:any){return <Card title="Audit Activity"><div className="space-y-2">{data.audit.map((x:any)=><div key={x.id} className="rounded-xl border p-3"><b>{x.action}</b><div className="text-xs text-muted-foreground">{x.created_at?new Date(x.created_at).toLocaleString():""} · {x.target_id||""}</div></div>)}{!data.audit.length&&<Empty text="No audit entries."/>}</div></Card>}
function Backup({data,token,notify}:any){const create=async()=>{try{await createAdminBackup(token,`Backup ${new Date().toLocaleString()}`);notify("Backup created.")}catch(e){notify(e instanceof Error?e.message:"Backup failed")}};return <Card title="Backup & Restore"><Btn primary onClick={()=>void create()}><FileArchive size={15}/>Create backup</Btn><div className="mt-4 space-y-2">{data.backups.map((b:any)=><div key={b.id} className="flex items-center gap-3 rounded-xl border p-3"><div className="flex-1"><b>{b.label}</b></div><Btn onClick={()=>void restoreAdminBackup(token,b.id).then(()=>notify("Backup restored to Draft."))}><RefreshCw size={15}/>Restore</Btn></div>)}</div></Card>}
function Trash({data,token,notify}:any){return <Card title="Trash & Recovery" action={<Btn danger onClick={()=>void emptyTrash(token).then(()=>notify("Trash emptied."))}><Trash2 size={15}/>Empty Trash</Btn>}><div className="space-y-2">{data.trash.map((x:any)=><div key={x.id} className="flex items-center gap-3 rounded-xl border p-3"><div className="flex-1"><b>{x.label}</b><div className="text-xs text-muted-foreground">{x.entity_type}</div></div><Btn onClick={()=>void restoreTrashItem(token,x.id).then(()=>notify("Item restored."))}>Restore</Btn><Btn danger onClick={()=>void deleteTrashItem(token,x.id).then(()=>notify("Recovery item deleted."))}><Trash2 size={15}/></Btn></div>)}{!data.trash.length&&<Empty text="Trash is empty."/>}</div></Card>}
function Publishing({token,notify}:any){const [versions,setVersions]=useState<any[]>([]);useEffect(()=>{void fetch("/api/admin-advanced?action=versions",{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>setVersions(d.versions||[])).catch(()=>setVersions([]))},[token]);return <Card title="Publishing & Version History"><div className="mb-4 rounded-xl border border-dashed p-4 text-sm text-muted-foreground">Draft → Preview → Validation → Publish. Restore returns a version to Draft.</div>{versions.map(v=><div key={v.id} className="mb-2 rounded-xl border p-3"><b>Version {v.version_no}</b><div className="text-xs text-muted-foreground">{v.status}</div></div>)}</Card>}
function Diagnostics({notify}:any){const [ran,setRan]=useState(false);return <Card title="Testing & Diagnostics" action={<Btn primary onClick={()=>{setRan(true);notify("Diagnostics completed.")}}><ShieldCheck size={15}/>Run diagnostics</Btn>}>{ran?<div className="grid gap-3 md:grid-cols-3">{["Website","Performance","Automated tests","Application cache","Code splitting","Diagnostics"].map(x=><div key={x} className="rounded-xl border p-3"><b>{x}</b><div className="text-xs text-muted-foreground">Checked</div></div>)}</div>:<Empty text="Run diagnostics to inspect the documented test and performance areas."/>}</Card>}function inferFields(module:AdminModule,selected:string):FieldSpec[]{const raw=SUB_FIELDS[module.id+"."+selected];if(raw)return raw.split("|").map(label=>{const lower=label.toLowerCase();let type:FieldType="text";if(/save|preview|view|manage|move|delete|add|edit|import|export|retry|cancel|complete|restore|generate|change|clear|update|run |download|copy|publish|unpublish|logout|revoke|support|ticket|bug|feature|terms|privacy|license|credit/.test(lower))type="action";else if(/toggle|enable|visible|show |hide |sticky|autoplay|mute|dismissible|anonymous|upload|spam protection|required|event lock|analytics collection|event unlock/.test(lower))type="toggle";else if(/colour|color/.test(lower))type="color";else if(/date & time|datetime/.test(lower))type="datetime";else if(/^date|date$/.test(lower))type="date";else if(/time/.test(lower))type="time";else if(/url|link|instagram|facebook|youtube|twitter|whatsapp/.test(lower))type="url";else if(/password|security code|secret|anonymous key|service role key|api key/.test(lower))type="password";else if(/number|count|duration|version|size|page|visitors|guests|views|sessions|storage usage/.test(lower))type="number";else if(/status|role|theme|font|language|format|timezone|type|filter|visibility|schedule/.test(lower))type="select";else if(/description|message|address|notes|configuration|logs|results|list|activities|pages|order|requirements/.test(lower))type="textarea";return {key:label.toLowerCase().replace(/[^a-z0-9]+/g,"_"),label,type,options:type==="select"?(/role/.test(lower)?COMMON_SELECTS.role:/theme/.test(lower)?COMMON_SELECTS.theme:/language/.test(lower)?COMMON_SELECTS.language:/format/.test(lower)?COMMON_SELECTS.dateFormat:/status/.test(lower)?COMMON_SELECTS.status:/visibility/.test(lower)?["Public","Private"]:["All","Enabled","Disabled"]):undefined};});return FIELD_HINTS[module.id]?.map((label,i)=>field(label,"field_"+i))||[field(title(selected),"value"),f("enabled","Enabled","toggle"),f("notes","Notes","textarea")]}

